// src/components/menubar-item.js
var MENUBAR_ITEM_KEYS = {
  ArrowDown: "_keyOpen",
  Enter: "_keyOpen",
  " ": "_keyOpen",
  Escape: "_keyClose",
  ArrowRight: "_keyMove",
  ArrowLeft: "_keyMove"
};

