      `style="${this._esc(style)}"`,
      'role="radiogroup"',
      `aria-label="${this._esc(this.label)}"`,
      this.readonly ? 'aria-readonly="true"' : "",
      this.disabled ? 'aria-disabled="true"' : "",
      theme ? `w-theme="${this._esc(theme)}"` : "",
      `data-value="${this._formatValue(selectedValue)}"`
