    "timer",
    "timer-color",
    "reverse-timer",
    "closable",
    "close-text",
    "prepend-icon",
    "prepend-avatar",
    "transition",
    "origin",
    "target",
    "absolute",
    "contained",
    "content-class",
    "opacity",
    "z-index",
    "close-on-back",
    "open-on-click",
    "open-on-hover",
    "open-on-focus",
