    "mandatory",
    "selectable",
    "selected",
    "select-strategy",
    "selected-color",
    "true-icon",
    "false-icon",
    "indeterminate-icon",
    "opened",
    "open-all",
    "open-on-click",
    "return-object",
    "search",
    "filter-keys",
    "filter-mode",
    "no-filter",
    "no-data-text",
    "hide-no-data",
    "filterable",
    "density",
    "lines",
    "slim",
    "variant",
    "hoverable",
    "rounded",
    "color",
    "disabled",
    "fluid",
    "indent",
    "prepend-gap",
    "indent-lines",
    "indent-lines-color",
    "indent-lines-opacity",
    "separate-roots",
