// src/components/data-table-virtual.js
class WDataTableVirtual extends WDataTable {
  static attrs = [...WDataTable.attrs, "item-height", "item-key"];
  get itemHeight() {
    return Math.max(1, this.hasAttribute("item-height") ? wNumberAttr(this, "item-height", 48) : 48);
  }
  get height() {
    return this._attr("height", "400px");
  }
  get fixedHeader() {
    return wBoolAttr(this, "fixed-header", wBoolAttr(this, "sticky", true));
  }
  get itemValue() {
    return this._attr("item-value", "") || this._attr("item-key", "");
  }
  _visibleRows() {
    return this._sorted(this._filtered());
  }
  _template() {
    const cols = this.columns;
    if (!cols.length)
      return `<div class="w-table-wrap"><slot></slot></div>`;
    const head = this.hideDefaultHeader ? "" : `<thead>${this._headHtml(cols, this._visibleRows())}</thead>`;
    const rootClasses = "w-data-table w-data-table--virtual" + this._cls({ "w-data-table--loading": this.loading });
    return `<div class="${rootClasses}" style="--w-virtual-row-height:${this.itemHeight}px">
      ${this.loading ? '<span class="w-data-table-loader" aria-hidden="true"></span>' : ""}
      <div class="${this._wrapClasses()}" style="height:${this._esc(this.height)};overflow:auto" data-virtual-scroll>
        <table class="${this._tableClasses()}">
          ${head}
          <tbody data-virtual-body></tbody>
          ${this._footerSlotHtml(cols)}
        </table>
      </div>
    </div>`;
  }
  _wrapClasses() {
    return super._wrapClasses() + this._cls({ "w-table-wrap--fixed-footer": this.fixedFooter });
  }
  _footerSlotHtml(cols) {
    if (!this.querySelector('[slot="footer"]'))
      return "";
    return `<tfoot><tr><td colspan="${this._span(cols)}"><slot name="footer"></slot></td></tr></tfoot>`;
  }
  _entries(rows) {
    if (!this._groupKey())
      return rows.map((item, index2) => ({ item, index: index2 }));
    const entries = [];
    let index = 0;
    for (const group of this._groups(rows)) {
      entries.push({ group });
      if (this._groupOpen(group.id))
        group.items.forEach((item, i) => entries.push({ item, index: index + i }));
      index += group.items.length;
    }
    return entries;
  }
  _renderWindow() {
    const scroller = this._q("[data-virtual-scroll]");
    const tbody = this._q("[data-virtual-body]");
    if (!scroller || !tbody)
      return;
    if (this.hideDefaultBody) {
      tbody.innerHTML = "";
      return;
    }
    const cols = this.columns;
    const rows = this._visibleRows();
    const message = this._messageHtml(rows, this._span(cols));
    if (message !== null) {
      tbody.innerHTML = message;
      return;
    }
    tbody.innerHTML = this._windowHtml(this._entries(rows), cols, scroller);
    this._bindWindowEvents();
  }
  _windowHtml(entries, cols, scroller) {
    const rowHeight = this.itemHeight;
    const { start, end } = this._window(scroller, entries.length, rowHeight);
    let html = this._spacerHtml(cols, start * rowHeight);
    for (let i = start;i < end; i++)
      html += this._entryHtml(entries[i], cols);
    return html + this._spacerHtml(cols, (entries.length - end) * rowHeight);
  }
  _window(scroller, count, rowHeight) {
    const viewport = scroller.clientHeight || Number.parseInt(this.height, 10) || 400;
    const overscan = 4;
    const start = Math.max(0, Math.floor(scroller.scrollTop / rowHeight) - overscan);
    const end = Math.min(count, start + Math.ceil(viewport / rowHeight) + overscan * 2);
    return { start, end };
  }
  _spacerHtml(cols, height) {
    if (height <= 0)
      return "";
    return `<tr aria-hidden="true" style="height:${height}px"><td colspan="${this._span(cols)}"></td></tr>`;
  }
  _entryHtml(entry, cols) {
    if (entry.group)
      return this._groupHeaderHtml(entry.group, this._span(cols));
    return this._rowHtml(entry.item, entry.index, cols);
  }
  _events() {
    super._events();
    this._q("[data-virtual-scroll]")?.addEventListener("scroll", () => this._renderWindow());
    this._renderWindow();
  }
  _bindWindowEvents() {
    this._qAll("[data-virtual-body] [data-select]").forEach((box) => box.addEventListener("change", (event) => {
      event.stopPropagation();
      this._toggleSelect(box.getAttribute("data-select"), event.target.checked);
    }));
    this._bindExpandEvents();
    this._bindGroupEvents();
  }
  _rerender() {
    const top = this._q("[data-virtual-scroll]")?.scrollTop || 0;
    super._rerender();
    const scroller = this._q("[data-virtual-scroll]");
    if (scroller && top) {
      scroller.scrollTop = top;
      this._renderWindow();
    }
  }
}
if (!customElements.get("w-data-table-virtual"))
  customElements.define("w-data-table-virtual", WDataTableVirtual);

// src/components/date-picker-controls.js
var VIEW_FOR = { month: "months", year: "year", mode: "year" };
var CONTROL_LABELS = { month: "Select month", year: "Select year", mode: "Toggle year selection" };

class WDatePickerControls extends WElement {
  static attrs = [
    "text",
    "active",
    "prev-icon",
    "next-icon",
    "mode-icon",
    "control-height",
    "control-variant",
    "no-month-picker",
    "month-text",
    "year-text",
    "view-mode"
  ];
  get text() {
    return this._attr("text", "");
  }
  get activeList() {
    return wValueList(this._attr("active", ""));
  }
  get prevIcon() {
    return this._attr("prev-icon", "‹");
  }
  get nextIcon() {
    return this._attr("next-icon", "›");
  }
  get modeIcon() {
    return this._attr("mode-icon", "▾");
  }
  get monthText() {
    return this._attr("month-text", "");
  }
  get yearText() {
    return this._attr("year-text", "");
  }
  get noMonthPicker() {
    return this._bool("no-month-picker");
  }
  get viewMode() {
    return this._attr("view-mode", "month");
  }
  get controlVariant() {
    return this._attr("control-variant", "docked") === "modal" ? "modal" : "docked";
  }
  get controlHeight() {
    const raw = this._attr("control-height", "").trim();
    if (!raw)
      return "";
    return /^-?\d*\.?\d+$/.test(raw) ? `${raw}px` : raw;
  }
  _template() {
    const controls = this.controlVariant === "modal" ? this._modalControls() : this._dockedControls();
    return `<div class="w-date-picker-controls w-date-picker-controls--${this.controlVariant}"${this._styleAttr()}>` + this._textTemplate() + controls + this._navTemplate() + "<slot></slot></div>";
  }
  _styleAttr() {
    const height = this.controlHeight;
    return height ? ` style="--w-date-picker-control-height:${this._esc(height)}"` : "";
  }
  _textTemplate() {
    return this.text ? `<span class="w-date-picker-controls__text">${this._esc(this.text)}</span>` : "";
  }
  _dockedControls() {
    return this._controlButton("month", this.monthText, "months") + this._controlButton("year", this.yearText, "year");
  }
  _modalControls() {
    const control = this.noMonthPicker ? "year" : "month";
    const label = [this.monthText, this.yearText].filter(Boolean).join(" ");
    return this._controlButton(control, label, VIEW_FOR[control]) + this._controlButton("mode", "", "year");
  }
  _controlButton(control, label, view) {
    const expanded = this.viewMode === view;
    const active = expanded || this.activeList.includes(control);
    const icon = `<span class="w-date-picker-controls__mode" aria-hidden="true">${this._esc(this.modeIcon)}</span>`;
    return `<button class="w-date-picker-controls__btn w-date-picker-controls__btn--${control}${active ? " active" : ""}"` + ` type="button" data-control="${control}" aria-expanded="${expanded}"` + this._attrs({ "aria-pressed": active && "true", "aria-label": !label && CONTROL_LABELS[control] }) + `>${this._esc(label)}${icon}</button>`;
  }
  _navTemplate() {
    return '<span class="w-date-picker-controls__nav">' + `<button class="w-date-picker-controls__btn w-date-picker-controls__btn--prev" type="button" data-control="prev" aria-label="Previous">${this._esc(this.prevIcon)}</button>` + `<button class="w-date-picker-controls__btn w-date-picker-controls__btn--next" type="button" data-control="next" aria-label="Next">${this._esc(this.nextIcon)}</button>` + "</span>";
  }
  _events() {
    this._qAll("[data-control]").forEach((button) => {
      button.addEventListener("click", () => this._activate(button.getAttribute("data-control")));
    });
  }
  _activate(control) {
    this._emit("change", { control, viewMode: this.viewMode });
    const view = VIEW_FOR[control];
    if (!view)
      return;
    const value = this.viewMode === view ? "month" : view;
    this._silentSet("view-mode", value);
    this._render();
    this._events();
    this._emit("update:view-mode", { value, control });
  }
}
if (!customElements.get("w-date-picker-controls")) {
  customElements.define("w-date-picker-controls", WDatePickerControls);
}

