// src/components/time-picker-clock.js
class WTimePickerClock extends WElement {
  static attrs = [
    "value",
    "min",
    "max",
    "step",
    "ampm",
    "format",
    "double",
    "rotate",
    "displayed-value",
    "allowed-values",
    "scrollable"
  ];
  get ampm() {
    return wBoolAttr(this, "ampm");
  }
  get min() {
    return wNumberAttr(this, "min", this.ampm ? 1 : 0);
  }
  get max() {
    return wNumberAttr(this, "max", this.ampm ? 12 : 59);
  }
  get step() {
    return Math.max(1, wNumberAttr(this, "step", this.ampm ? 1 : 5));
  }
  get double() {
    return wBoolAttr(this, "double");
  }
  get rotate() {
    return wNumberAttr(this, "rotate", 0);
  }
  get scrollable() {
    return wBoolAttr(this, "scrollable");
  }
  get displayedValue() {
    return this._attr("displayed-value", "");
  }
  get format() {
    return this._attr("format", this.ampm ? "ampm" : "24hr") === "ampm" ? "ampm" : "24hr";
  }
  get value() {
    return wNumberAttr(this, "value", this.min);
  }
  get locked() {
    return this.hasAttribute("disabled") || this.hasAttribute("readonly");
  }
  get allowedValues() {
    return wNumberList(this.getAttribute("allowed-values"), []);
  }
  _allowed(value) {
    const list = this.allowedValues;
    return !list.length || list.includes(value);
  }
  _values() {
    const values = [];
    for (let value = this.min;value <= this.max; value += this.step)
      values.push(value);
    return values;
  }
  _perRing(count) {
    return this.double ? Math.ceil(count / 2) : Math.max(1, count);
  }
  _angle(index, perRing) {
    return this.rotate + index % perRing * (360 / perRing);
  }
  _label(value) {
    return this.format === "24hr" ? pad(value) : String(value);
  }
  _itemHtml(value, index, perRing) {
    const angle = this._angle(index, perRing);
    const radians = angle * Math.PI / 180;
    const radius = index < perRing ? 42 : 30;
    const selected = value === this.value;
    const allowed = this._allowed(value);
    return `<button type="button" role="option"` + ` class="w-time-picker-clock-item${selected ? " selected" : ""}${allowed ? "" : " disabled"}"` + ` style="left:${(50 + Math.sin(radians) * radius).toFixed(3)}%;top:${(50 - Math.cos(radians) * radius).toFixed(3)}%"` + this._attrs({
      "data-clock-value": String(value),
      "aria-selected": String(selected),
      tabindex: selected ? "0" : "-1",
      disabled: this.locked || !allowed
    }) + `>${this._esc(this._label(value))}</button>`;
  }
  _handHtml(values, perRing) {
    const index = values.indexOf(this.value);
    if (index < 0)
      return "";
    const inner = index >= perRing ? " w-time-picker-hand--inner" : "";
    return `<span class="w-time-picker-hand${inner}" style="--w-time-picker-angle:${this._angle(index, perRing)}deg"></span>`;
  }
  _centerHtml() {
    if (!this.displayedValue)
      return "";
    return `<span class="w-time-picker-clock-display">${this._esc(this.displayedValue)}</span>`;
  }
  _template() {
    const values = this._values();
    const perRing = this._perRing(values.length);
    const items = values.map((value, index) => this._itemHtml(value, index, perRing)).join("");
    return `<div class="w-time-picker-clock" role="listbox" aria-label="Clock"` + `${this.scrollable ? " data-clock-scrollable" : ""}>` + `${items}${this._handHtml(values, perRing)}${this._centerHtml()}<slot></slot></div>`;
  }
  _events() {
    const dial = this._q(".w-time-picker-clock");
    if (!dial)
      return;
    this._qAll("[data-clock-value]").forEach((button) => {
      button.addEventListener("click", () => this._select(Number(button.getAttribute("data-clock-value"))));
    });
    dial.addEventListener("keydown", (event) => this._onKeydown(event));
    if (this.scrollable)
      dial.addEventListener("wheel", (event) => this._onWheel(event));
  }
  _onKeydown(event) {
    const next = this._keyTarget(event.key);
    if (next === null)
      return;
    event.preventDefault();
    this._select(next);
    this._q(".w-time-picker-clock-item.selected")?.focus();
  }
  _keyTarget(key) {
    const forward = key === "ArrowRight" || key === "ArrowUp";
    const back = key === "ArrowLeft" || key === "ArrowDown";
    if (forward || back)
      return this._step(forward);
    if (key === "Home")
      return this._edge(false);
    if (key === "End")
      return this._edge(true);
    return null;
  }
  _edge(last) {
    const allowed = this._values().filter((value) => this._allowed(value));
    if (!allowed.length)
      return null;
    return last ? allowed[allowed.length - 1] : allowed[0];
  }
  _step(forward) {
    const values = this._values();
    const size = values.length;
    const start = values.indexOf(this.value);
    for (let offset = 1;offset <= size; offset += 1) {
      const index = ((start + (forward ? offset : -offset)) % size + size) % size;
      if (this._allowed(values[index]))
        return values[index];
    }
    return this.value;
  }
  _onWheel(event) {
    if (this.locked)
      return;
    event.preventDefault();
    this._select(this._step(event.deltaY < 0));
  }
  _select(value) {
    if (this.locked || value === null || !this._allowed(value))
      return;
    if (value === this.value)
      return;
    this._silentSet("value", value);
    this._render();
    this._events();
    this._emit("input", { value });
    this._emit("change", { value });
  }
}
if (!customElements.get("w-time-picker-clock")) {
  customElements.define("w-time-picker-clock", WTimePickerClock);
}

// src/components/time-picker-controls.js
var W_UNITS = [
  { unit: "hour", hint: "Hour", allowed: "allowed-hours" },
  { unit: "minute", hint: "Minute", allowed: "allowed-minutes" },
  { unit: "second", hint: "Second", allowed: "allowed-seconds" }
];

class WTimePickerControls extends WElement {
  static attrs = [
    "value",
    "hour",
    "minute",
    "second",
    "period",
    "view-mode",
    "ampm",
    "use-seconds",
    "input-hints",
    "min",
    "max",
    "allowed-hours",
    "allowed-minutes",
    "allowed-seconds"
  ];
  get ampm() {
    return wBoolAttr(this, "ampm");
  }
  get useSeconds() {
    return wBoolAttr(this, "use-seconds");
  }
  get inputHints() {
    return wBoolAttr(this, "input-hints");
  }
  get period() {
    const attr = this._periodAttr();
    return attr || (this.parts.hour >= 12 ? "pm" : "am");
  }
  _periodAttr() {
    const attr = String(this._attr("period", "")).toLowerCase();
    return attr === "am" || attr === "pm" ? attr : "";
  }
  get viewMode() {
    const view = this._attr("view-mode", "hour");
    return W_UNITS.some((entry) => entry.unit === view) ? view : "hour";
  }
  get parts() {
    const parts = parseTime(this._attr("value", "12:00"));
    W_UNITS.forEach(({ unit }) => {
      const raw = this.getAttribute(unit);
      if (raw !== null && raw !== "")
        parts[unit] = Math.max(0, parseInt(raw, 10) || 0);
    });
    return this._withPeriod(parts);
  }
  _withPeriod(parts) {
    const attr = this._periodAttr();
    if (!attr)
      return parts;
    parts.hour = parts.hour % 12 + (attr === "pm" ? 12 : 0);
    return parts;
  }
  _label(unit, parts) {
    if (unit !== "hour" || !this.ampm)
      return pad(Math.min(59, parts[unit]));
    return pad(parts.hour % 12 || 12);
  }
  _allowed(unit, value, parts) {
    const entry = W_UNITS.find((item) => item.unit === unit);
    const list = wNumberList(this.getAttribute(entry.allowed), []);
    if (list.length && !list.includes(value))
      return false;
    const seconds = timeValue({ ...parts, [unit]: value }, this.useSeconds);
    return seconds >= timeValue(this._bound("min"), this.useSeconds) && seconds <= timeValue(this._bound("max"), this.useSeconds);
  }
  _bound(name) {
    const fallback = name === "min" ? { hour: 0, minute: 0, second: 0 } : { hour: 23, minute: 59, second: 59 };
    return parseLimit(this.getAttribute(name), fallback);
  }
  _periodHour(period, parts) {
    return parts.hour % 12 + (period === "pm" ? 12 : 0);
  }
  _units() {
    return this.useSeconds ? W_UNITS : W_UNITS.slice(0, 2);
  }
  _controlHtml(entry, parts) {
    const active = this.viewMode === entry.unit;
    const allowed = this._allowed(entry.unit, parts[entry.unit], parts);
    const button = `<button type="button" class="w-time-picker-display${active ? " active" : ""}"` + this._attrs({
      "data-time-view": entry.unit,
      "aria-pressed": String(active),
      "aria-invalid": allowed ? "" : "true",
      "aria-label": entry.hint
    }) + `>${this._esc(this._label(entry.unit, parts))}</button>`;
    const hint = this.inputHints ? `<span class="w-time-picker-hint">${entry.hint}</span>` : "";
    return `<span class="w-time-picker-control">${button}${hint}</span>`;
  }
  _periodButton(period, parts) {
    const current = this.period === period;
    const allowed = this._allowed("hour", this._periodHour(period, parts), parts);
    return `<button type="button" class="${current ? "active" : ""}"` + this._attrs({
      "data-time-period": period,
      "aria-pressed": String(current),
      disabled: !allowed
    }) + `>${period.toUpperCase()}</button>`;
  }
  _periodHtml(parts) {
    if (!this.ampm)
      return "";
    return '<div class="w-time-picker-period" role="group" aria-label="Period">' + this._periodButton("am", parts) + this._periodButton("pm", parts) + "</div>";
  }
  _template() {
    const parts = this.parts;
    const controls = this._units().map((entry) => this._controlHtml(entry, parts)).join('<span class="w-time-picker-separator">:</span>');
    return '<div class="w-time-picker-controls w-time-picker-header" role="group">' + `${controls}${this._periodHtml(parts)}<slot></slot></div>`;
  }
  _events() {
    this._qAll("[data-time-view]").forEach((button) => {
      button.addEventListener("click", () => this._setView(button.getAttribute("data-time-view")));
    });
    this._qAll("[data-time-period]").forEach((button) => {
      button.addEventListener("click", () => this._setPeriod(button.getAttribute("data-time-period")));
    });
  }
  _locked() {
    return this.hasAttribute("disabled") || this.hasAttribute("readonly");
  }
  _rerender() {
    this._render();
    this._events();
  }
  _setView(view) {
    if (this._locked())
      return;
    this._silentSet("view-mode", view);
    this._rerender();
    this._emit("update:view-mode", { viewMode: view });
  }
  _setPeriod(period) {
    if (this._locked())
      return;
    this._silentSet("period", period);
    this._rerender();
    this._emit("update:period", { period });
  }
}
if (!customElements.get("w-time-picker-controls")) {
  customElements.define("w-time-picker-controls", WTimePickerControls);
}

